CREATE FUNCTION public.guard_academic_attempt_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE used integer; bankkey text; BEGIN IF EXISTS(SELECT 1 FROM public.practice_attempts WHERE id=NEW.id) THEN RETURN NEW; END IF; IF NOT NEW.verified_scoring THEN RETURN NEW; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0)); bankkey:=regexp_replace(regexp_replace(NEW.deck_id,'~f[0-9]+$',''),'-s[0-9]+$',''); IF NEW.assessment_mode='exam' THEN SELECT count(*) INTO used FROM public.practice_attempts WHERE user_id=NEW.user_id AND assessment_mode='exam' AND certification_subject=NEW.certification_subject AND verified_scoring; IF used>=2 THEN RAISE EXCEPTION 'Ha utilizado los dos simulacros de esta materia'; END IF; ELSE SELECT count(*) INTO used FROM public.practice_attempts WHERE user_id=NEW.user_id AND assessment_mode='practice' AND verified_scoring AND regexp_replace(regexp_replace(deck_id,'~f[0-9]+$',''),'-s[0-9]+$','')=bankkey; IF used>=3 THEN RAISE EXCEPTION 'Ha utilizado los tres intentos de esta práctica'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER academic_attempt_limit BEFORE INSERT ON public.practice_attempts FOR EACH ROW EXECUTE FUNCTION public.guard_academic_attempt_limit();